#include <bits/stdc++.h>
using namespace std;

using UBitset = bitset<128>;

const int MOD = 1000000007;
const int INV = 570000004;

int add_mod(int a, int b) {
    int res = a + b;
    return res >= MOD ? res - MOD : res;
}

int sub_mod(int a, int b) {
    int res = a - b;
    return res < 0 ? res + MOD : res;
}

int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

unordered_map<UBitset, int> index_map;
int node_id, time_idx, children[65536][128];

int dfs(UBitset s) {
    auto it = index_map.find(s);
    if (it != index_map.end()) return it->second;
    int id = time_idx++;
    index_map[s] = id;
    for (int mask = 0; mask < (1 << node_id); ++mask) {
        UBitset new_s = s;
        for (int j = 0; j < (1 << node_id); ++j) {
            if (!new_s[j]) {
                for (int k = mask & j; k; k ^= k & -k) {
                    if (s[j ^ (k & -k)]) {
                        new_s[j] = 1;
                        break;
                    }
                }
            }
        }
        children[id][mask] = dfs(new_s);
    }
    return id;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
    int n;
    cin >> n;
    dfs(UBitset(1));
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
        cin >> p[i][j];
        p[i][j] = mul_mod(p[i][j], INV);
    }
    for (int i = 0; i < n; ++i) for (int j = 0; j < (1 << n); ++j) {
        q[i][j] = 1;
        for (int k = 0; k < n; ++k) {
            int val = (j >> k) & 1 ? p[k][i] : sub_mod(1, p[k][i]);
            q[i][j] = mul_mod(q[i][j], val);
        }
    }
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < node_id; ++j) {
            for (int k = 0; k < (1 << n); ++k) {
                int next_state = children[j][k];
                dp[i + 1][next_state] = add_mod(dp[i + 1][next_state], mul_mod(dp[i][j], q[i][k]));
            }
        }
    }
    UBitset res;
    for (int i = 0; i < (1 << n); ++i) res[i] = 1;
    cout << dp[n][index_map[res]] << endl;
}
